@startuml

class Club {}

class Director {}

class Scout {
  + ScoutKind : ScoutKind
}

class HeadScout extends Scout {}

class HeadCoach {}

class Player {
  + Status : ScoutingStatus
}

class PlayerProfile {
  + Position : Position
}

class PlayerAttribute {
  + Name : string
  + Value : int
}

class LongList {}

class ScoutingAssignment {}

class ScoutingReport {
  + Pros : string
  + Cons : string
  + Recommendation : Recommendation
}

class Offer {}

enum ScoutKind {
  HEAD_SCOUT
}

enum ScoutingStatus {
  SHORT_LISTED
}

enum Position {
  GK
  LB
}

enum Recommendation {
  KEY_PLAYER
  FIRST_TEAM_PLAYER
  RESERVE_TEAM_PLAYER
  PROSPECTIVE_PLAYER
  NOT_A_GOOD_SIGNING
}

Club "1" *-- "1" Director
Club "1" *-- "0..*" Scout
Club "1" *-- "0..*" HeadCoach
Club "1" *-- "0..*" Player

HeadCoach "1" -- "0..*" PlayerProfile : identifies
PlayerProfile "1" *-- "0..*" PlayerAttribute

Scout "1" -- "0..*" LongList : notes
LongList "1" -- "0..*" ScoutingAssignment : evaluated by
Scout "1" -- "0..*" ScoutingAssignment : carries out
ScoutingAssignment "1" -- "1" ScoutingReport : results in
ScoutingAssignment "0..*" -- "1" Player : investigates

HeadCoach "1" -- "0..*" Player : decides to move to short list
HeadScout "1" -- "0..*" Player : decides to move to short list

Director "1" -- "0..*" Offer : makes
Player "1" -- "0..*" Offer : receives

@enduml

